import XCTest

@testable import ReticulumSwift

/// Creating a release as an `rngit` client does, measured against Python RNS 1.5.4.
///
/// The reference takes its artifacts in the order `os.listdir` answers, which
/// the filesystem decides. The port sorts them, and the corpus was recorded
/// with that same ordering pinned, so every byte below is the reference's own.
///
/// Every byte but the signatures: Ed25519 signing is randomised here and
/// deterministic in the reference, so what a signature covers is compared and
/// the signature itself is verified rather than matched.
final class RNGitClientCreateReleaseTests: XCTestCase {

  private struct Named: Equatable {
    let name: String
    let bytes: String
  }

  /// One of the entries a run starts with, a directory where it has no bytes.
  private struct Given {
    let name: String
    let bytes: String?
  }

  private struct Ran: Equatable {
    let arguments: [String]
    let directory: String?
  }

  private enum Edits {
    case writes(String)
    case code(Int32)
    case none
  }

  private struct Request: Equatable {
    let path: String
    let fields: String
    let timeout: Double
  }

  private struct Run {
    let label: String
    let remote: String?
    let target: String?
    let signer: String?
    let name: String?
    let signerFile: Bool
    let noUpload: Bool
    let files: [Given]
    let edits: Edits
    let commit: String?
    let git: Bool
    let hasPath: Bool
    let recalls: Bool
    let linkComesUp: Bool
    let answers: [RNGitRequestResult]
    let written: String
    let aborted: String?
    let requests: [Request]
    let tornDown: Bool
    let ran: [Ran]
    let suffixes: [String]
    let left: [Named]
  }

  /// One run of the notes editor on its own.
  private struct Notes {
    let label: String
    let tag: String?
    let edits: Edits
    let written: String
    let returned: String?
    let handed: [String]
    let suffixes: [String]
  }

  private static let privateKey =
    "3b1f5c9a7d2e4086b5c3a19f7e6d4c2b8a09f1e3d5c7b9a1f3e5d7c9b1a3f5e79c8b7a6f5e4d3c2b1a0f9e8d7c6b5a4938271605f4e3d2c1b0a9f8e7d6c5b4a3"
