  /// Holds what the client wrote.
  private final class Recorder: RNGitClientOutput {
    var written = ""
    func write(_ text: String) { written += text }
  }

  /// Stands in for the user's editor, holding what it was handed and where.
  private final class Scribe: RNGitClientEditor {
    private let edits: Edits
    var handed: [String] = []
    var suffixes: [String] = []

    init(_ edits: Edits) { self.edits = edits }

    func editor() -> String {
      if case .none = edits { return "" }
      return "editor-under-test"
    }

    func run(_ editor: String, over path: String) -> Int32 {
      handed.append((try? String(contentsOfFile: path, encoding: .utf8)) ?? "")
      suffixes.append("." + (path as NSString).pathExtension)
      switch edits {
      case .writes(let text):
        try? text.write(toFile: path, atomically: true, encoding: .utf8)
        return 0
      case .code(let code): return code
      case .none: return 0
      }
    }
  }

  /// Answers the `git` a run says is there, holding what it was asked.
  private final class Git: RNGitCommandRunner {
    private let vector: Run
    var ran: [Ran] = []

    init(_ vector: Run) { self.vector = vector }

    func run(_ executable: String, arguments: [String], in directory: String?)
      -> RNGitCommandOutput?
    {
      ran.append(Ran(arguments: [executable] + arguments, directory: directory))
      guard vector.git else { return nil }
      if arguments.first == "--version" {
        return RNGitCommandOutput(
          status: 0, standardOutput: "git version 2.0.0\n", standardError: "")
      }
      guard let commit = vector.commit else {
        return RNGitCommandOutput(
          status: 128, standardOutput: "", standardError: "fatal: bad revision\n")
      }
      return RNGitCommandOutput(status: 0, standardOutput: commit + "\n", standardError: "")
    }
  }

  /// Answers a client the way one run says to, holding what it was asked.
  private final class Stub: RNGitClientTransport {
    private var answers: [RNGitRequestResult]
    private let vector: Run?
    var requests: [Request] = []
    var awaitHash: String?
    var awaitTimeout: Double?
    var tornDown = false

    init(_ vector: Run? = nil) {
      self.vector = vector
      self.answers = vector?.answers ?? []
    }

    func mediumPathTimeout() -> TimeInterval { 1606 }

    func awaitPath(to destinationHash: Data, timeout: TimeInterval) -> Bool {
      awaitHash = destinationHash.hexString
      awaitTimeout = timeout
      return vector?.hasPath ?? false
    }

    func recallIdentity(for destinationHash: Data) -> Identity? {
      vector?.recalls == true ? Identity() : nil
    }

    func establishLink(to identity: Identity) -> Bool { vector?.linkComesUp ?? false }

    func request(
      _ path: RNGitRequestPath, _ fields: MsgPack.Value, timeout: TimeInterval,
      progress: ((RNGitTransferProgress) -> Void)?
    ) -> RNGitClientResponse {
      requests.append(
        Request(path: path.rawValue, fields: MsgPack.encode(fields).hexString, timeout: timeout))
      return RNGitClientResponse(
        result: answers.isEmpty ? .bytes(Data([0])) : answers.removeFirst())
    }

    func teardown() { tornDown = true }
  }

  /// `value` with every signature it carries blanked.
  ///
  /// Ed25519 signing is randomised here, so a recorded signature can never be reproduced, while
  /// everything it covers can be. A signed container is 64 bytes of signature in front of a
  /// msgpack envelope, and an envelope can carry further containers, so this walks what it
  /// decodes.
  private static func blinded(_ value: MsgPack.Value) -> MsgPack.Value {
    switch value {
    case .bytes(let data):
      guard data.count > RSG.signatureLength,
        let envelope = try? MsgPack.decode(Data(data.dropFirst(RSG.signatureLength))),
        envelope.asDictionary?["hashtype"] != nil
      else { return value }
      return .array([.bytes(Data(count: RSG.signatureLength)), blinded(envelope)])
    case .array(let items):
      return .array(items.map(blinded))
    case .map(let entries):
      return .map(entries.map { (blinded($0.0), blinded($0.1)) })
    default:
      return value
    }
  }

  /// `file` with every signature it carries blanked.
  private static func blinded(_ file: Named) -> Named {
    let bytes = Data(pythonHex: file.bytes) ?? Data()
    return Named(name: file.name, bytes: MsgPack.encode(blinded(.bytes(bytes))).hexString)
  }

  /// `request` with every signature its fields carry blanked.
  private static func blinded(_ request: Request) -> Request {
    let fields = (try? MsgPack.decode(Data(pythonHex: request.fields) ?? Data())) ?? .nil
    return Request(
      path: request.path, fields: MsgPack.encode(blinded(fields)).hexString,
      timeout: request.timeout)
  }

  func testCreatingAReleaseMatchesTheReference() throws {
    let identity = try XCTUnwrap(Identity.fromBytes(Data(pythonHex: Self.privateKey)!))
    let own = try XCTUnwrap(Identity.fromBytes(Data(pythonHex: Self.signerKey)!))

    for run in Self.runs {
      let directory = NSTemporaryDirectory() + "rngit-create-" + UUID().uuidString
      try FileManager.default.createDirectory(
        atPath: directory, withIntermediateDirectories: true)
      defer { try? FileManager.default.removeItem(atPath: directory) }
      for file in run.files {
        guard let bytes = file.bytes else {
          try FileManager.default.createDirectory(
            atPath: directory + "/" + file.name, withIntermediateDirectories: false)
          continue
        }
        FileManager.default.createFile(
          atPath: directory + "/" + file.name, contents: Data(pythonHex: bytes)!)
      }

      let signerPath = directory + "-signer"
      if run.signerFile { try own.toFile(URL(fileURLWithPath: signerPath)) }
      defer { try? FileManager.default.removeItem(atPath: signerPath) }

      let output = Recorder()
      let transport = Stub(run)
      let scribe = Scribe(run.edits)
      let git = Git(run)
      let commands = RNGitClientCommands(
        identity: identity, now: { Date(timeIntervalSince1970: TimeInterval(Self.when)) },
        transport: transport, output: output, editor: scribe, runner: git)

      var aborted: String?
      do {
        try commands.createRelease(
          remote: run.remote, target: run.target?.replacingOccurrences(of: "DIR", with: directory),
          signer: run.signerFile ? signerPath : run.signer, name: run.name,
          noUpload: run.noUpload)
      } catch let abort as RNGitClientAbort {
        aborted = abort.message
      }

      let written = output.written
        .replacingOccurrences(of: signerPath, with: "SIGNER")
        .replacingOccurrences(of: directory, with: "DIR")
      XCTAssertEqual(written, run.written, run.label)
      XCTAssertEqual(aborted, run.aborted, run.label)
      XCTAssertEqual(
        transport.requests.map(Self.blinded), run.requests.map(Self.blinded), run.label)
      XCTAssertEqual(transport.tornDown, run.tornDown, run.label)
      XCTAssertEqual(git.ran, run.ran, run.label)
      XCTAssertEqual(scribe.suffixes, run.suffixes, run.label)

      var left: [Named] = []
      for name in (try FileManager.default.contentsOfDirectory(atPath: directory)).sorted() {
        var isDirectory: ObjCBool = false
        FileManager.default.fileExists(
          atPath: directory + "/" + name, isDirectory: &isDirectory)
        if isDirectory.boolValue { continue }
        let bytes = try Data(contentsOf: URL(fileURLWithPath: directory + "/" + name))
        left.append(Named(name: name, bytes: bytes.hexString))
      }
      XCTAssertEqual(left.map(Self.blinded), run.left.map(Self.blinded), run.label)

      let signed = [
        "." + RNGitClientCommands.signatureExtension,
        "." + RNGitClientCommands.messageExtension,
      ]
      let signer = run.signerFile ? own : identity
      for file in left where signed.contains(where: file.name.hasSuffix) {
        let bytes = Data(pythonHex: file.bytes) ?? Data()
        XCTAssertTrue(
          signer.validate(
            signature: bytes.prefix(RSG.signatureLength),
            for: Data(bytes.dropFirst(RSG.signatureLength))), file.name + ", " + run.label)
      }
    }
  }

  func testEditingReleaseNotesMatchesTheReference() {
    for run in Self.notes {
      let output = Recorder()
      let scribe = Scribe(run.edits)
      let commands = RNGitClientCommands(transport: Stub(), output: output, editor: scribe)

      let made = run.tag.map { commands.releaseNotes(tag: $0) } ?? commands.releaseNotes()

      XCTAssertEqual(output.written, run.written, run.label)
      XCTAssertEqual(made, run.returned, run.label)
      XCTAssertEqual(scribe.handed, run.handed, run.label)
      XCTAssertEqual(scribe.suffixes, run.suffixes, run.label)
    }
  }

}
